const $=s=>document.querySelector(s), results=$('#results'),input=$('#word');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>s.toLowerCase().replaceAll('ё','е').normalize('NFD').replace(/[\u0300\u0301]/g,'').normalize('NFC').trim();
const shard=s=>[...norm(s)].slice(0,2).map(c=>c.codePointAt(0).toString(16)).join('-')||'5f';
const cache=new Map();
async function data(kind,s){const key=kind+'-'+shard(s);if(!cache.has(key))cache.set(key,(async()=>{let r=await fetch('data/'+key+'.bin');if(r.status===404)return {};if(!r.ok)throw Error('Не удалось загрузить словарь');if(!('DecompressionStream' in window))throw Error('Ваш браузер не поддерживает сжатые данные словаря. Попробуйте современную версию браузера.');let stream=r.body.pipeThrough(new DecompressionStream('gzip'));return JSON.parse(await new Response(stream).text())})());return cache.get(key)}
const flatten=x=>Array.isArray(x)?x.flatMap(flatten):x&&typeof x==='object'?[x]:[];
function split(s){let a=[],level=0,start=0;for(let i=0;i<s.length;i++){if(s[i]==='('||s[i]==='[')level++;if(s[i]===')'||s[i]===']')level--;if(s[i]===','&&level===0){a.push(s.slice(start,i));start=i+1}}a.push(s.slice(start));return a}
const pos={'с':'существительное','п':'прилагательное','г':'глагол','мс':'местоимение','мс-п':'местоименное прилагательное','числ':'числительное','числ-п':'счётное прилагательное','н':'наречие','предл':'предлог','союз':'союз','част':'частица','межд':'междометие','предик':'предикатив','вводн':'вводное слово','сравн':'сравнительная степень'};
const cases=['Именительный','Родительный','Дательный','Винительный','Творительный','Предложный'];
const adjCases=['Именительный','Родительный','Дательный','Винительный · неодуш.','Винительный · одуш.','Творительный','Предложный'];
function adjLabel(i){if(i<28){let group=Math.floor(i/7);return adjCases[i%7]+' · '+['муж. род','жен. род','ср. род','мн. число'][group]}return ['Краткая форма · муж. род','Краткая форма · жен. род','Краткая форма · ср. род','Краткая форма · мн. число','Сравнительная степень'][i-28]||'Форма '+(i+1)}
function label(t,i){if(t==='с')return cases[i%6]+' · '+(i<6?'ед. число':'мн. число');if(t==='п')return adjLabel(i);if(t==='мс-п'||t==='числ-п')return adjLabel(i);if(t==='мс')return cases[i]||'Форма '+(i+1);if(t==='числ')return ['Именительный','Родительный','Дательный','Винительный · неодуш.','Винительный · одуш.','Творительный','Предложный'][i]||'Форма '+(i+1);if(t==='г'){let basic=['Инфинитив','Прошедшее · муж. род','Прошедшее · жен. род','Прошедшее · ср. род','Прошедшее · мн. число',...['1 л. ед.','2 л. ед.','3 л. ед.','1 л. мн.','2 л. мн.','3 л. мн.'].map(x=>'Настоящее · '+x),...['1 л. ед.','2 л. ед.','3 л. ед.','1 л. мн.','2 л. мн.','3 л. мн.'].map(x=>'Будущее · '+x),'Повелительное · ед. число','Повелительное · мн. число','Деепричастие · настоящее','Деепричастие · прошедшее'];if(i<basic.length)return basic[i];let n=i-basic.length;return ['Причастие действ. наст.','Причастие действ. прош.','Причастие страд. наст.','Причастие страд. прош.'][Math.floor(n/32)]+' · '+adjLabel(n%32)}return 'Форма '+(i+1)}
function makeForms(entry){if(!Object.hasOwn(entry,'п'))return null;let good=[],uncertain=[],missingBase=false;String(entry['п']).split(';').forEach((cell,i)=>{let rowGood=[],rowUncertain=[];for(let part of split(cell)){if(part==='-'||part.endsWith('-'))continue;let marker=part.endsWith('?')?'предположительная':part.endsWith('*')?'затруднительная':'';part=part.replace(/[?*]$/,'');let annotation=(part.match(/\([^)]*\)|\[[^\]]*\]/g)||[]).join(' ');part=part.replace(/\([^)]*\)|\[[^\]]*\]/g,'');let m=part.match(/^([1-5])/),key='о'+(m?m[1]:'');if(!Object.hasOwn(entry,key)){missingBase=true;continue}let form=String(entry[key]??'')+(m?part.slice(1):part);if(!form)continue;let value=form+(annotation?' '+annotation:'')+(marker?' ('+marker+')':'');(marker?rowUncertain:rowGood).push(value)}if(rowGood.length)good.push([label(entry.с?.т,i),rowGood.join(', ')]);if(rowUncertain.length)uncertain.push([label(entry.с?.т,i),rowUncertain.join(', ')])});return {good,uncertain,missingBase}}
function rows(list){return '<div class="forms">'+list.map(([a,b])=>`<div class="form-row"><span class="label">${esc(a)}</span><span class="value">${esc(b)}</span></div>`).join('')+'</div>'}
function card(lemma,obj){let entries=flatten(obj);return entries.map((e,i)=>{let p=e.с||{},info=[pos[p.т]||p.т,({'м':'мужской род','ж':'женский род','с':'средний род'}[p.р]||p.р),({'о':'одушевлённое','н':'неодушевлённое'}[p.о]||''),({'св':'совершенный вид','нсв':'несовершенный вид','св-нсв':'двувидовой'}[p.гв]||'')].filter(Boolean).join(' · ');let f=makeForms(e);let meaning=[e.з,e.з2,e.з3].filter(Boolean).join(' · ');return `<article class="card"><div class="card-head"><div><h3>${esc(lemma)}</h3><div class="meta">${esc(info)}${meaning?'<br>'+esc(meaning):''}</div></div>${entries.length>1?`<span class="badge">Вариант ${i+1} / ${entries.length}</span>`:''}</div>${f?`<div class="variant"><div class="variant-title">Словоформы</div>${f.good.length?rows(f.good):'<p class="meta">Достоверные формы в источнике не приведены.</p>'}${f.uncertain.length?`<div class="uncertain"><h4>Формы с оговорками</h4><div class="note">Согласно пометам словаря, эти формы предположительны или затруднительны.</div>${rows(f.uncertain)}</div>`:''}${f.missingBase?'<p class="note">Часть форм не удалось раскрыть из данных источника.</p>':''}</div>`:'<p class="meta">Для этой статьи парадигма в источнике не приведена.</p>'}</article>`}).join('')}
let serial=0;async function search(raw){let q=norm(raw),id=++serial;if(!q)return;if(!/^[а-яё-]+$/iu.test(raw.trim().normalize('NFC').replace(/[\u0300\u0301]/g,''))){results.innerHTML='<div class="state">Введите одно русское слово. Допускаются дефис и знак ударения.</div>';return}results.innerHTML='<div class="state">Ищем в словаре…</div>';try{let idx=await data('i',q),matches=idx[q]||[];if(id!==serial)return;if(!matches.length){results.innerHTML=`<div class="result-head"><div><div class="eyebrow">РЕЗУЛЬТАТ ПОИСКА</div><h2>${esc(raw)}</h2></div></div><div class="state">В словаре ничего не найдено. Проверьте написание или попробуйте другое слово.</div>`;return}let maps=await Promise.all(matches.map(x=>data('d',x)));if(id!==serial)return;results.innerHTML=`<div class="result-head"><div><div class="eyebrow">РЕЗУЛЬТАТ ПОИСКА</div><h2>${esc(raw)}</h2></div><p>Найдено слов: ${matches.length}</p></div>`+matches.map((m,i)=>card(m,maps[i][m])).join('');results.scrollIntoView({behavior:'smooth',block:'start'})}catch(e){if(id===serial)results.innerHTML=`<div class="state">Не удалось выполнить поиск: ${esc(e.message)}. Попробуйте ещё раз.</div>`}}
$('#search').addEventListener('submit',e=>{e.preventDefault();search(input.value)});document.querySelectorAll('[data-word]').forEach(b=>b.addEventListener('click',()=>{input.value=b.dataset.word;search(input.value)}));
